{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret siger, at Udbetaling Danmark kan indhente en lægeattest fra den praktiserende læge, når dokumentationen ikke rækker. Det siger også, at attesten skal beskrive funktionsevnen i forhold til den ansøgte funktionsnedsættelse og behovet for behandling eller henvisning til specialist. Alt det stemmer med afsnit 5.1.2 og rubrikken. Svaret indeholder ingen af rubrikkens væsentlige fejl: automatisk indhentning, kun diagnose, at lægen afgør sagen, eller attest som ubetinget erstatning for dokumentationskravet."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: muligheden for at indhente attest fra den praktiserende læge, funktionsevne i forhold til den søgte funktionsnedsættelse, og behov for fortsat behandling eller henvisning til yderligere udredning eller specialistbehandling."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Begge dele af spørgsmålet besvares: hvad Udbetaling Danmark kan gøre, og hvad attesten skal beskrive. Svaret indeholder ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner hverken vejledningen, et afsnit, en bestemmelse eller en anden identificerbar kilde. Det er kun almindelig tekst."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde støtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle påstande kan genfindes i afsnit 5.1.2: indhentning ved utilstrækkelig dokumentation, attestens indhold, fremmøde som udgangspunkt, yderligere journaloplysninger i særlige tilfælde og udgifter afholdt af styrelsen. Svaret tilføjer ingen regler uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger \"kan\" om indhentning og bevarer forbeholdet \"i særlige tilfælde\" for journaloplysninger. Det gengiver også \"som udgangspunkt\" om fremmøde. Attesten fremstår ikke som automatisk pligt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er kort og konsistent. Først kommer muligheden for at indhente attest, derefter attestens indhold og supplerende forhold, uden indbyrdes modstrid."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "\"Kan\" bruges om skønsmæssig indhentning, \"skal\" om attestens indhold, og \"som udgangspunkt\" om fremmøde. Det svarer til kilden. Formuleringen \"Ansøgeren skal som udgangspunkt møde op\" er en mindre forenkling af \"skal medvirke ... som udgangspunkt med fremmøde\", men ændrer ikke meningen."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "yes",
      "reason": "Svaret dækker alle led i punktet: indhentning af lægeattest fra den praktiserende læge, når funktionsniveauet ikke kan vurderes, attestens indhold, fremmøde som udgangspunkt, yderligere journaloplysninger i særlige tilfælde og at styrelsen afholder udgifterne."
    }
  },
  "overall_notes": "Svaret er juridisk korrekt og dækker alle kritiske og supplerende elementer i rubrikken, uden unøjagtigheder i modaliteten. Det angiver dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

